import assert from 'node:assert/strict';
import test from 'node:test';

import { normalizeContentWarnings, normalizeLanguageCodes, normalizeSubtitleTracks } from '../lib/content-metadata';
import {
  VALID_STATUS_TRANSITIONS,
  getValidNextStatuses,
  isValidStatusTransition,
} from '../lib/report-status';

test('valid report status transitions are explicit and consistent', () => {
  assert.deepEqual(VALID_STATUS_TRANSITIONS.DRAFT, ['REVIEWED', 'SUPERSEDED']);
  assert.deepEqual(getValidNextStatuses('REVIEWED'), ['APPROVED', 'DRAFT', 'SUPERSEDED']);
  assert.equal(isValidStatusTransition('APPROVED', 'ISSUED'), true);
  assert.equal(isValidStatusTransition('ISSUED', 'APPROVED'), true);
  assert.equal(isValidStatusTransition('PAID', 'APPROVED'), false);
});

test('metadata normalization strips invalid values and normalizes casing', () => {
  assert.deepEqual(normalizeLanguageCodes([' EN ', 'fr', 'fr', 'xx']), ['en', 'fr']);
  assert.deepEqual(normalizeContentWarnings([' Violence ', 'violence', 'drama', '  sex ']), ['violence', 'sex']);
  assert.deepEqual(
    normalizeSubtitleTracks([
      {
        label: ' English ',
        languageCode: ' EN ',
        kind: 'subtitles',
        fileKey: 'uploads/creator-1/subtitles/english.vtt ',
        isDefault: true,
      },
      {
        label: 'French',
        languageCode: 'fr',
        kind: 'captions',
        fileKey: 'uploads/creator-1/subtitles/french.vtt',
        isDefault: false,
      },
      {
        label: '',
        languageCode: 'xx',
        kind: 'captions',
        fileKey: 'uploads/creator-1/subtitles/bad.vtt',
      },
    ]),
    [
      {
        label: 'English',
        languageCode: 'en',
        kind: 'subtitles',
        fileKey: 'uploads/creator-1/subtitles/english.vtt',
        isDefault: true,
      },
      {
        label: 'French',
        languageCode: 'fr',
        kind: 'captions',
        fileKey: 'uploads/creator-1/subtitles/french.vtt',
        isDefault: false,
      },
    ],
  );
});

import {
  CONTENT_WARNING_OPTIONS,
  LANGUAGE_OPTIONS,
  SUBTITLE_KIND_OPTIONS,
  type ContentWarningValue,
  type SubtitleKindValue
} from '@/lib/media-types';

type LanguageCode = (typeof LANGUAGE_OPTIONS)[number]['code'];

export type SubmittedSubtitleTrack = {
  label: string;
  languageCode: string;
  kind: SubtitleKindValue;
  fileKey: string;
  isDefault?: boolean;
};

const LANGUAGE_CODES = new Set<string>(LANGUAGE_OPTIONS.map((option) => option.code));
const CONTENT_WARNING_VALUES = new Set<string>(CONTENT_WARNING_OPTIONS.map((option) => option.value));
const SUBTITLE_KIND_VALUES = new Set<string>(SUBTITLE_KIND_OPTIONS.map((option) => option.value));

export function isSupportedLanguageCode(value: string | undefined): value is LanguageCode {
  return Boolean(value && LANGUAGE_CODES.has(value));
}

export function normalizeLanguageCodes(values: string[] = []) {
  return Array.from(
    new Set(
      values
        .map((value) => value.trim().toLowerCase())
        .filter((value) => LANGUAGE_CODES.has(value))
    )
  );
}

export function normalizeContentWarnings(values: string[] = []) {
  return Array.from(
    new Set(
      values
        .map((value) => value.trim().toLowerCase())
        .filter((value): value is ContentWarningValue => CONTENT_WARNING_VALUES.has(value))
    )
  );
}

export function normalizeSubtitleTracks(values: SubmittedSubtitleTrack[] = []) {
  return values
    .map((value) => ({
      label: value.label.trim(),
      languageCode: value.languageCode.trim().toLowerCase(),
      kind: value.kind,
      fileKey: value.fileKey.trim(),
      isDefault: Boolean(value.isDefault)
    }))
    .filter((value) => value.label && value.fileKey && LANGUAGE_CODES.has(value.languageCode) && SUBTITLE_KIND_VALUES.has(value.kind));
}

export type RoleValue = 'USER' | 'CREATOR' | 'ADMIN';
export type SignupIntentValue = 'VIEWER' | 'CREATOR';
export type CreatorAccessStatusValue = 'NONE' | 'REQUESTED' | 'INVITED' | 'SUBMITTED';
export type SupportTicketStatusValue = 'OPEN' | 'IN_PROGRESS' | 'RESOLVED';
export type SupportTicketCategoryValue =
  | 'PAYMENT'
  | 'ACCOUNT_ACCESS'
  | 'CATALOG_HELP'
  | 'CREATOR_ONBOARDING'
  | 'VIDEO_UPLOAD'
  | 'CONTRACTS'
  | 'OTHER';
export type PriceTierValue = 'SNACK' | 'STANDARD' | 'PREMIERE';
export type VideoStatusValue =
  | 'DRAFT'
  | 'PENDING'
  | 'APPROVED'
  | 'REJECTED'
  | 'MASTER_UPLOADED'
  | 'PROCESSING'
  | 'READY'
  | 'PUBLISHED'
  | 'ARCHIVED';
export type VideoTypeValue = 'FEATURE' | 'SERIES' | 'SHORT' | 'SKIT' | 'DOCUMENTARY' | 'ADVERT';
export type AgeRatingValue = 'ALL' | 'PG13' | 'PG16' | 'PG18';
export type SubtitleKindValue = 'subtitles' | 'captions' | 'sdh';
export type ContentWarningValue =
  | 'violence'
  | 'sex'
  | 'nudity'
  | 'strong_language'
  | 'substance_use'
  | 'self_harm'
  | 'horror'
  | 'abuse';

export const LANGUAGE_OPTIONS = [
  { code: 'en', label: 'English' },
  { code: 'fr', label: 'French' },
  { code: 'ar', label: 'Arabic' },
  { code: 'sw', label: 'Swahili' },
  { code: 'ha', label: 'Hausa' },
  { code: 'yo', label: 'Yoruba' },
  { code: 'ig', label: 'Igbo' },
  { code: 'am', label: 'Amharic' },
  { code: 'zu', label: 'Zulu' },
  { code: 'xh', label: 'Xhosa' },
  { code: 'af', label: 'Afrikaans' },
  { code: 'pt', label: 'Portuguese' },
  { code: 'es', label: 'Spanish' }
] as const;

export const CONTENT_WARNING_OPTIONS = [
  { value: 'violence', label: 'Violence' },
  { value: 'sex', label: 'Sex' },
  { value: 'nudity', label: 'Nudity' },
  { value: 'strong_language', label: 'Strong language' },
  { value: 'substance_use', label: 'Substance use' },
  { value: 'self_harm', label: 'Self-harm' },
  { value: 'horror', label: 'Horror or disturbing scenes' },
  { value: 'abuse', label: 'Abuse or exploitation' }
] as const;

export const SUBTITLE_KIND_OPTIONS = [
  { value: 'subtitles', label: 'Subtitles' },
  { value: 'captions', label: 'Closed captions' },
  { value: 'sdh', label: 'SDH' }
] as const;

export function getLanguageLabel(code: string) {
  return LANGUAGE_OPTIONS.find((option) => option.code === code)?.label ?? code.toUpperCase();
}

export function getContentWarningLabel(value: string) {
  return CONTENT_WARNING_OPTIONS.find((option) => option.value === value)?.label ?? value;
}

export const VALID_STATUS_TRANSITIONS: Record<string, string[]> = {
  DRAFT: ['REVIEWED', 'SUPERSEDED'],
  REVIEWED: ['APPROVED', 'DRAFT', 'SUPERSEDED'],
  APPROVED: ['ISSUED', 'REVIEWED', 'SUPERSEDED'],
  ISSUED: ['PAID', 'APPROVED', 'SUPERSEDED'],
  PAID: ['SUPERSEDED'],
  SUPERSEDED: []
};

export function getValidNextStatuses(status: string): string[] {
  return VALID_STATUS_TRANSITIONS[status] ?? [];
}

export function isValidStatusTransition(currentStatus: string, nextStatus: string): boolean {
  if (currentStatus === nextStatus) return true;
  const validNext = VALID_STATUS_TRANSITIONS[currentStatus];
  return validNext ? validNext.includes(nextStatus) : false;
}
